        elif stmt.msg == bad_cond_1_msg:
            if len(stmt.data) > 0:
                domain = 'cond'
                field = 'fact_id_1'
                sample = dict(zip(stmt.fields, stmt.data[0]))

        elif stmt.msg == bad_cond_2_msg:
            if len(stmt.data) > 0:
                domain = 'cond'
